from rcb_client import Robot
import numpy as np
r=Robot(); s=r.spec(); R=np.asarray(s['qpos']['range']); p=np.asarray(r.observe(images=False)['proprio']['joint_pos']);
# Re-assert this test's intended standing target: measured start posture, with modestly straighter knees.
body=np.array([.005,.001,-.391,.506,-.410,.007,-.009,-.395,.494,-.393,.001,-.004,-.002,-.009,-.008,.003,.002,-.008,.007,.006,-.005])
a=np.zeros(61)
for i,x in enumerate(body):
 lo,hi=R[i];a[i]=np.clip(2*(x-lo)/(hi-lo)-1,-1,1)
for i,j in ((21,16),(22,17),(41,45),(42,46)):
 lo,hi=R[i];a[i]=np.clip(2*(p[j]-lo)/(hi-lo)-1,-1,1)
hand=[.35,.65,0,.35,.8,0,.85,2.65,0,.85,2.65,0,.85,2.65,.25,0,.85,2.65]
for st in (23,43):
 for k,x in enumerate(hand):
  lo,hi=R[st+k];a[st+k]=2*(x-lo)/(hi-lo)-1
for _ in range(14):
 o=r.step('qpos',np.tile(a,(25,1)),images=False)
 print(o['step'],o['done'],o['reason'],np.round(o['imu']['gravity'],2),np.round([o['proprio']['joint_pos'][3],o['proprio']['joint_pos'][8]],2))
 if o['done']: break
